import React from 'react';
import type * as Stitches from '@stitches/react';
import { IconProps } from '@hexa-ui/icons';
import { config, useTheme } from '@hexa-ui/theme';
import { StyledButton, StyledIconContainer } from './Button.styles';
import { LoadingDots } from '../spinner';

type CSSVariants = Stitches.CSS<typeof config>;
export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'destructive';
  size?: 'small' | 'medium' | 'large';
  elevated?: boolean;
  leading?: boolean;
  trailing?: boolean;
  icon?: React.FunctionComponent<IconProps>;
  isLoading?: boolean;
  children: React.ReactNode;
  css?: CSSVariants;
}

export const ButtonComponent = (
  {
    variant = 'primary',
    size = 'medium',
    elevated = false,
    leading,
    trailing,
    icon: Icon,
    isLoading,
    children,
    onClick,
    ...props
  }: ButtonProps,
  forwardedRef: React.ForwardedRef<HTMLButtonElement>
): JSX.Element => {
  const theme = useTheme();
  return (
    <StyledButton
      variant={variant}
      size={size}
      elevated={elevated}
      leading={leading}
      trailing={trailing}
      {...props}
      onClick={isLoading ? undefined : onClick}
      className={`${props.className ? props.className : ''} ${theme}`}
      ref={forwardedRef}
    >
      {Icon && leading && (
        <StyledIconContainer leading={leading} trailing={trailing} size={size}>
          <Icon />
        </StyledIconContainer>
      )}
      {isLoading ? <LoadingDots color={variant === 'primary' ? 'colorful' : 'mono'} /> : children}
      {Icon && trailing && (
        <StyledIconContainer leading={leading} trailing={trailing} size={size}>
          <Icon />
        </StyledIconContainer>
      )}
    </StyledButton>
  );
};

export const Button = React.forwardRef(ButtonComponent);
export default Button;
